import { describe, it, expect } from "vitest";
import { randomUUID } from "node:crypto";
import { idFromSlug, slugFor, storyPath, topicSlug } from "./slug";

describe("topicSlug", () => {
  it("lowercases and joins words with a dash", () => {
    expect(topicSlug("Dinosaurios Gigantes")).toBe("dinosaurios-gigantes");
  });

  it("strips Latin accents", () => {
    expect(topicSlug("Canción")).toBe("cancion");
  });

  it("keeps non-Latin letters", () => {
    expect(topicSlug("恐竜の世界")).toBe("恐竜の世界");
    expect(topicSlug("الديناصورات")).toBe("الديناصورات");
  });

  it("collapses punctuation and spaces into single dashes with none at the ends", () => {
    expect(topicSlug("  ¡Hola,   mundo!!  ")).toBe("hola-mundo");
    expect(topicSlug("a --- b ... c")).toBe("a-b-c");
  });

  it("caps the result at 60 characters without a trailing dash", () => {
    const long = topicSlug("a".repeat(100));
    expect(long).toBe("a".repeat(60));

    // The 60-character cut lands on the dash between the words.
    const cut = topicSlug(`${"a".repeat(59)} ${"b".repeat(20)}`);
    expect(cut).toBe("a".repeat(59));
    expect(cut.length).toBeLessThanOrEqual(60);
    expect(cut.endsWith("-")).toBe(false);
  });

  it("falls back to t-<hex> for an emoji-only topic", () => {
    const slug = topicSlug("🦖🦕");
    expect(slug).toMatch(/^t-[0-9a-f]+$/);
    expect(topicSlug("🦖🦕")).toBe(slug);
    expect(topicSlug("🐙")).not.toBe(slug);
  });
});

describe("slugFor / idFromSlug", () => {
  it("round-trips a randomUUID-shaped id", () => {
    const id = randomUUID();
    const slug = slugFor({ id, topic: "Dinosaurios Gigantes" });
    expect(slug).toBe(`${id}--dinosaurios-gigantes`);
    expect(idFromSlug(slug)).toBe(id);
  });

  it("round-trips a hand-written ref-es-mx id", () => {
    const id = "ref-es-mx-la-sombra-del-faro";
    const slug = slugFor({ id, topic: "La sombra del faro" });
    expect(slug).toBe(`${id}--la-sombra-del-faro`);
    expect(idFromSlug(slug)).toBe(id);
  });

  it("returns the bare id when there is no separator", () => {
    const id = randomUUID();
    expect(idFromSlug(id)).toBe(id);
    expect(idFromSlug("ref-es-mx-la-sombra")).toBe("ref-es-mx-la-sombra");
  });

  it("returns null for an empty string", () => {
    expect(idFromSlug("")).toBeNull();
  });

  it("returns null for a value containing a colon", () => {
    expect(idFromSlug("pool:es-AR:dinosaurios")).toBeNull();
    expect(idFromSlug("pool:es-AR:dinosaurios--tema")).toBeNull();
  });
});

describe("storyPath", () => {
  it("is /s/ followed by the slug", () => {
    const record = { id: randomUUID(), topic: "Canción" };
    expect(storyPath(record)).toBe(`/s/${slugFor(record)}`);
    expect(storyPath(record).startsWith("/s/")).toBe(true);
  });
});

